def score(f, p, hw, w):
    sm = np.maximum(f.tm_crit_ratio, f.tm_l2_ratio)
    t = np.sqrt(np.square(sm) + np.square(f.tm_dram_ratio))
    s = 10.0 * np.log2(t)
    s = s + f.splitk_excess_log * w[0]
    s = s + np.log2(f.mainloop_sync_count) * w[1]
    if p.working_set_l2_ratio <= 1.0:
        if p.roofline_ratio < 1.0:
            s = s + f.occupancy_deficit * w[2]
        else:
            s = s + f.occupancy_deficit * w[3]
        if p.log_flops < 30.0:
            s = s + (1000.0 * f.instruction_density) * w[4]
        else:
            s = s + (1000.0 * f.instruction_density) * w[5]
        if p.unaligned_access_fraction > 0.01:
            s = s + f.tm_regstaged * w[6]
        else:
            s = s + f.tm_regstaged * w[7]
        if p.output_parallelism_deficit > 0.001:
            if p.log_min_dim < 6.0:
                s = s + np.log2(f.cta_edge_balance_time_ratio) * w[8]
                s = s + f.launch_wave_utilization_deficit * w[9]
                s = s + f.raster_band_l2_pressure * w[10]
                s = s + f.log_roofline_time_mraster * w[11]
            else:
                s = s + np.log2(f.cta_edge_balance_time_ratio) * w[12]
                s = s + f.launch_wave_utilization_deficit * w[13]
                s = s + f.raster_band_l2_pressure * w[14]
                s = s + f.log_roofline_time_mraster * w[15]
